"""Generate transparent repository decorators for one-shot regression I/O failures."""

from pathlib import Path
import re

ROOT = Path(__file__).resolve().parents[2]
REPOSITORIES = {
    "Shared": "sharedRepository",
    "UserSettings": "userSettingsRepository",
    "SettingsAI": "settingsAIRepository",
    "UltrasoundReport": "ultrasoundReportRepository",
    "UltrasoundDraft": "ultrasoundDraftRepository",
    "Template": "templateRepository",
}


def generate() -> str:
    result = [
        "// Generated by test/scripts/repository_adapters.py. Delegates all non-failing calls to real repositories.",
        "#if DEBUG && DOGLYAD_REGRESSION",
        "import Foundation",
        "import DoglyadNetwork",
        "import DoglyadNeuralModel",
        "",
        "@MainActor",
        "enum RegressionRepositoryAdapters {",
        "    static func prepareNavigation(on process: InitializationProcess) async throws {",
        "        try RegressionFixtures.prepareSpeechStorage()",
        '        if UserDefaults.standard.bool(forKey: "regressionResetLegalConsent") {',
        "            try await process.sharedRepository!.acceptLegal(documentDate: .distantPast)",
        "        }",
        "    }",
        "    static func install(on process: InitializationProcess) {",
        "        guard !(process.templateRepository is RegressionTemplateRepository) else { return }",
        "        let faults = RegressionRepositoryFaults()",
    ]
    for name, prop in REPOSITORIES.items():
        result.append(
            f"        process.{prop} = Regression{name}Repository(wrapped: process.{prop}!, faults: faults)"
        )
    result += [
        "        let model = process.applicationConfig!.ultrasound.examinationNeuralModel",
        "        process.examinationNeuralModelFactory = DNeuralUltrasoundModelFactory(",
        "            locale: process.language!.currentLocale,",
        "            proposalPrompt: model.proposalPrompt,",
        "            parameters: DNeuralGenerationParameters(temperature: model.temperature, maxTokens: model.maxTokens, maxContextTokens: model.maxContextTokens),",
        "            parseDictation: process.ultrasoundReportRepository!.parseDictation",
        "        )",
        "    }",
        "}",
        "",
        "@MainActor",
        "final class RegressionRepositoryFaults {",
        "    @TaskLocal static var module: String?",
        '    private let operation = UserDefaults.standard.string(forKey: "regressionFault") ?? ""',
        '    private let targetModule = UserDefaults.standard.string(forKey: "regressionFaultModule") ?? ""',
        '    private var skip = UserDefaults.standard.integer(forKey: "regressionFaultAfter")',
        '    private let delayedOperation = UserDefaults.standard.string(forKey: "regressionDelay") ?? ""',
        '    private let delaySeconds = max(5, min(30, UserDefaults.standard.integer(forKey: "regressionDelaySeconds")))',
        "    private var delayConsumed = false",
        "    private var consumed = false",
        "",
        "    init() {}",
        "",
        "    func check(_ name: String) async throws {",
        "        if !delayConsumed, name == delayedOperation {",
        "            delayConsumed = true",
        "            try await Task.sleep(for: .seconds(delaySeconds))",
        "        }",
        "        guard !consumed, name == operation else { return }",
        "        guard targetModule.isEmpty || Self.module == targetModule else { return }",
        "        if skip > 0 { skip -= 1; return }",
        "        consumed = true",
        "        throw CocoaError(.fileWriteUnknown)",
        "    }",
        "}",
        "",
    ]
    for name, prop in REPOSITORIES.items():
        protocol = f"{name}RepositoryProtocol"
        path = next((ROOT / "ios/Doglyad/Repository").rglob(protocol + ".swift"))
        source = path.read_text()
        result += [
            "@MainActor",
            f"final class Regression{name}Repository: {protocol} {{",
            f"    private let wrapped: any {protocol}",
            "    private let faults: RegressionRepositoryFaults",
            f"    init(wrapped: any {protocol}, faults: RegressionRepositoryFaults) {{",
            "        self.wrapped = wrapped",
            "        self.faults = faults",
            "    }",
        ]
        methods = re.findall(r"func (\w+)\(([^)]*)\) async throws( -> [^\n]+)?", source)
        if len(methods) != len(re.findall(r"\bfunc ", source)):
            raise ValueError(f"Unsupported repository signature: {path}")
        for method, parameters, returns in methods:
            args = []
            for param in parameters.split(","):
                if not param.strip():
                    continue
                names = param.split(":")[0].split()
                args.append(
                    names[-1] if names[0] == "_" else names[0] + ": " + names[-1]
                )
            result += [
                f"    func {method}({parameters}) async throws{returns} {{",
                f'        try await faults.check("{prop}.{method}")',
            ]
            if name == "Template" and method == "getReadyMadeTemplates":
                result.append(
                    '        if UserDefaults.standard.bool(forKey: "regressionEmptyReadyMadeTemplates") { return [] }'
                )
            result += [
                f"        return try await wrapped.{method}(" + ", ".join(args) + ")",
                "    }",
            ]
        result += ["}", ""]
    return "\n".join(result + ["#endif", ""])


if __name__ == "__main__":
    (ROOT / "ios/Doglyad/Regression/RegressionRepositoryAdapters.swift").write_text(generate())
